'use strict';
const PLAYER_COLORS=['#8fe4d1','#ffd394'];
const sceneSound=(fallback='mallet')=>settings.sound==='auto'?fallback:settings.sound;
const sprite=new Image();sprite.src='assets/creatures.png';
const spriteRects={bird:[0,0,443,443],frog:[443,0,447,443],whale:[890,0,477,443],fish:[1367,0,407,443],jellyfish:[0,443,425,444],octopus:[425,443,475,444],shell:[900,443,420,444],crab:[1320,443,454,444]};
function character(name,x,y,size=170,active=0){const rect=spriteRects[name];if(!sprite.complete||!sprite.naturalWidth||!rect){circle(x,y,size*.35,'#c7e5cf');return;}const motion=settings.energy==='calm'?0:Math.sin(elapsed*3+Object.keys(spriteRects).indexOf(name))*active*8;g.save();g.translate(x,y+motion);g.scale(1+active*.035,1+active*.035);g.drawImage(sprite,...rect,-size/2,-size/2,size,size);g.restore();}

// A short, device-local performance: capture note timing, rests, and held lengths.
const transport={recording:false,playing:false,events:[],start:0,length:0,time:0,cursor:0,sceneId:null,
 capture(e){if(!this.recording||this.playing||this.events.length>=700)return null;const event={...e,time:elapsed-this.start,absoluteStart:elapsed};this.events.push(event);return event;},
 begin(){this.stop();endPointers();audio.stop();this.events=[];this.length=0;this.start=elapsed;this.sceneId=current.id;this.recording=true;syncTransport();toast('Recording your music — up to 30 seconds.');},
 finish(){if(!this.recording)return;endPointers();this.length=Math.max(.3,elapsed-this.start);this.events.forEach(e=>{if(e.sustain)e.duration=clamp(e.duration,.1,this.length-e.time+.1);});this.recording=false;syncTransport();toast(this.events.length?'Your music is ready to hear.':'No sounds recorded yet. Try again.');},
 replay(){if(this.recording)this.finish();if(!this.events.length){toast('Choose Create in Teacher settings, then Record some music.');return;}this.stop();endPointers();audio.stop();this.playing=true;this.time=0;this.cursor=0;ensureStart();syncTransport();},
 stop(){this.playing=false;syncTransport();},
 update(dt){if(this.recording){if(elapsed-this.start>=30)this.finish();else $('recordStatus').textContent='● Recording '+Math.floor(elapsed-this.start)+' / 30 seconds';}if(!this.playing)return;this.time+=dt;while(this.cursor<this.events.length&&this.events[this.cursor].time<=this.time){const e=this.events[this.cursor++];if(e.type==='drum')audio.drum(e.drum,e.velocity,e.pan);else audio.note({midi:e.midi},e.duration/(settings.sustain||1),e.kind,e.velocity,e.pan,false);pulse(600+(e.pan||0)*480,360,PLAYER_COLORS[e.pan<0?0:1],70);}if(this.time>this.length+1){this.stop();toast('That was your music.');}}
};
audio.capture=e=>transport.capture(e);
function syncTransport(){const r=$('recordBtn');r.textContent=transport.recording?'■ Finish recording':'● Record';r.setAttribute('aria-pressed',String(transport.recording));$('replayBtn').textContent=transport.playing?'■ Stop playback':'▷ Hear what we made';$('recordStatus').classList.toggle('visible',transport.recording||transport.playing);if(transport.playing)$('recordStatus').textContent='▷ Listening to your music';}

modules.squares=()=>{
 const s={pads:padPositions(settings.gridSize,settings.gridSize===15?3:2).map(a=>({...a,energy:0})),trails:[]};
 function enter(p,a){p.voice?.stop();p.cell=a?.i;if(!a)return;const x=a.x+a.w/2,y=a.y+a.h/2;a.energy=1;p.voice=audio.note(a.i,1,sceneSound('mallet'),.62,(x/W-.5),true);pulse(x,y,COLORS[a.i%8],a.w*.32);p.lastCenter={x,y};}
 return{state:s,down(p){enter(p,s.pads.find(a=>hitRect(p,a)));},move(p){const a=s.pads.find(a=>hitRect(p,a));if(a&&a.i!==p.cell){const before=p.lastCenter;enter(p,a);if(before)s.trails.push({from:before,to:p.lastCenter,c:PLAYER_COLORS[p.side||0],age:0});}},up(p){p.voice?.stop();},update(dt){s.pads.forEach(a=>a.energy=Math.max(0,a.energy-dt*.85));s.trails.forEach(a=>a.age+=dt);s.trails=s.trails.filter(a=>a.age<1.6);},draw(){s.pads.forEach(a=>{const held=[...pointers.values()].some(p=>p.cell===a.i),breathe=settings.energy==='calm'?0:Math.sin(elapsed*2.5+a.i)*.025;const cx=a.x+a.w/2,cy=a.y+a.h/2;g.save();g.translate(cx,cy);g.scale(held?.96:1,held?.96:1);const gr=g.createLinearGradient(0,-a.h/2,0,a.h/2);gr.addColorStop(0,COLORS[a.i%8]);gr.addColorStop(1,COLORS[a.i%8]+'bf');round(-a.w/2,-a.h/2,a.w,a.h,25,gr);if(held||a.energy>0){g.globalAlpha=held?.55+breathe:a.energy*.4;ring(0,0,Math.min(a.w,a.h)*(.23+(held?breathe:0)), '#ffffff',3);g.globalAlpha=1;}round(-a.w/2+12,-a.h/2+11,a.w-24,4,2,'#ffffff3d');if(settings.labels){text(noteName(a.i),0,0,39,'#143932');if(noteMidi(a.i)>=72)circle(0,34,4,'#14393280');}else{circle(0,0,9,'#23463780');}g.restore();});s.trails.forEach(t=>{g.globalAlpha=(1-t.age/1.6)*.7;line(t.from.x,t.from.y,t.to.x,t.to.y,t.c,6);g.globalAlpha=1;});}};
};

modules.gravity=()=>{
 const s={balls:[],platforms:[{x:90,y:325,w:290,i:0},{x:460,y:455,w:280,i:2},{x:825,y:330,w:285,i:4}],gravity:420,bounce:.82,serial:0};
 function drop(x=220,y=120,side=0){if(s.balls.length>=12)s.balls.shift();const b={x,y,vx:0,vy:0,r:21,i:s.serial++%8,age:0,cool:0,side};s.balls.push(b);return b;}
 return{state:s,actions:[action('Drop a ball',()=>drop()),action('Gravity: light / earth / heavy',()=>{s.gravity=s.gravity===420?680:s.gravity===680?220:420;toast('Gravity: '+(s.gravity===220?'light':s.gravity===420?'earth':'heavy'));}),action('Bounce: soft / lively / springy',()=>{s.bounce=s.bounce===.82?.96:s.bounce===.96?.58:.82;toast('Bounce: '+(s.bounce===.58?'soft':s.bounce===.82?'lively':'springy'));}),action('Clear balls',()=>s.balls=[])],down(p){const ball=nearest(p,s.balls,45);if(ball&&settings.interaction!=='touch'){p.ball=ball;ball.held=true;ball.vx=0;return;}const a=s.platforms.find(a=>p.x>a.x-15&&p.x<a.x+a.w+15&&Math.abs(p.y-a.y)<42);if(a){p.object=a;p.dx=p.x-a.x;p.dy=p.y-a.y;if(settings.tapOnly){a.y=a.y<250?530:a.y-75;}else if(settings.interaction==='create')a.i=(a.i+1)%8;play(a.i,p.x,a.y,sceneSound('mallet'),.8,.35);}else{p.ball=drop(p.x,clamp(p.y,105,600),p.side);}},move(p){if(p.object){p.object.x=clamp(p.x-p.dx,25,W-p.object.w-25);p.object.y=clamp(p.y-p.dy,200,590);}if(p.ball){p.ball.held=true;p.ball.x=p.x;p.ball.y=clamp(p.y,100,610);p.ball.vy=0;}},up(p){if(p.ball)p.ball.held=false;},update(dt){s.balls.forEach(b=>{b.age+=dt;b.cool-=dt;if(b.held)return;const old=b.y;b.vy+=s.gravity*dt;b.y+=b.vy*dt;for(const a of s.platforms)if(b.x>a.x&&b.x<a.x+a.w&&old+b.r<=a.y+2&&b.y+b.r>=a.y&&b.vy>0&&b.cool<=0){b.y=a.y-b.r;b.vy=-Math.max(145,b.vy*s.bounce);b.cool=.1;a.lit=.65;play(a.i,b.x,a.y,sceneSound('mallet'),1,.48);}if(b.y>635){b.y=635;b.vy=-Math.max(140,Math.abs(b.vy)*s.bounce);if(b.cool<=0){play(b.i,b.x,b.y,sceneSound('mallet'),.6,.25);b.cool=.15;}}});s.platforms.forEach(a=>a.lit=Math.max(0,(a.lit||0)-dt));s.balls=s.balls.filter(b=>b.age<45);},draw(){if(settings.players===2){text('DROP & LIFT',235,126,17,PLAYER_COLORS[0]);text('MOVE THE MUSICAL PLATFORMS',840,126,17,PLAYER_COLORS[1]);}s.platforms.forEach(a=>{if(a.lit)glow(a.x+a.w/2,a.y,180,COLORS[a.i]);round(a.x,a.y-9,a.w,22,11,COLORS[a.i]);round(a.x+12,a.y-4,a.w-24,3,2,'#ffffff55');label(a.i,a.x+a.w/2,a.y+42,24);});line(50,660,1150,660,'#b9dba02e',2);s.balls.forEach(b=>{const c=settings.players===2?PLAYER_COLORS[b.side||0]:COLORS[b.i];glow(b.x,b.y,55,c);circle(b.x,b.y,b.r,c);circle(b.x-5,b.y-6,5,'#ffffffa0');});text('Gravity '+(s.gravity===220?'light':s.gravity===420?'earth':'heavy')+'  ·  Bounce '+(s.bounce===.58?'soft':s.bounce===.82?'lively':'springy'),600,620,14,'#9bb8b1');}};
};

modules.marbles=()=>{
 const s={balls:[],platforms:[{x:140,y:190,w:690,slope:.13,i:0},{x:350,y:395,w:690,slope:-.13,i:1},{x:140,y:465,w:520,slope:.13,i:2}],selected:0,targets:Array.from({length:5},(_,i)=>({x:120+i*238,y:620,i})),serial:0};
 function release(){if(s.balls.length>=10)s.balls.shift();s.balls.push({x:195,y:125,vx:45,vy:0,r:15,age:0,i:s.serial++%8,last:-1,cool:0});}
 const createAction=(label,fn)=>({...action(label,fn),createOnly:true});
 return{state:s,actions:[action('Release marble',release),createAction('Tilt left',()=>{const a=s.platforms[s.selected];a.slope=clamp(a.slope-.06,-.4,.4);}),createAction('Tilt right',()=>{const a=s.platforms[s.selected];a.slope=clamp(a.slope+.06,-.4,.4);}),createAction('Add ramp',()=>{if(s.platforms.length<6){s.platforms.push({x:400,y:330,w:300,slope:.1,i:s.platforms.length});s.selected=s.platforms.length-1;}else toast('Six ramps is the maximum.');}),createAction('Remove ramp',()=>{if(s.platforms.length>1){s.platforms.splice(s.selected,1);s.selected=0;}}),action('Clear marbles',()=>s.balls=[])],down(p){const a=s.platforms.find(a=>p.x>a.x-15&&p.x<a.x+a.w+15&&Math.abs(p.y-a.y-(p.x-a.x)*a.slope)<40);if(a&&settings.interaction!=='touch'){s.selected=s.platforms.indexOf(a);p.object=a;p.dx=p.x-a.x;p.dy=p.y-a.y;if(settings.tapOnly)a.slope=a.slope>0?-.15:.15;}else{const t=nearest(p,s.targets,90);if(t){drum(t.i,t.x,t.y);t.lit=.4;}else release();}},move(p){if(p.object){p.object.x=clamp(p.x-p.dx,40,W-p.object.w-40);p.object.y=clamp(p.y-p.dy,160,520);}},update(dt){s.balls.forEach(b=>{b.age+=dt;b.cool-=dt;let remain=dt;while(remain>0){const step=Math.min(.008,remain);remain-=step;const ox=b.x,oy=b.y;b.vy+=440*step;b.x+=b.vx*step;b.y+=b.vy*step;for(let j=0;j<s.platforms.length;j++){const a=s.platforms[j],norm=Math.sqrt(1+a.slope*a.slope),oldDistance=(oy-a.y-(ox-a.x)*a.slope)/norm,newDistance=(b.y-a.y-(b.x-a.x)*a.slope)/norm;if(b.x>=a.x&&b.x<=a.x+a.w&&oldDistance<=-b.r+8&&newDistance>=-b.r&&b.vy-b.vx*a.slope>0){const nx=a.slope/norm,ny=-1/norm,vn=b.vx*nx+b.vy*ny;b.x+=nx*(newDistance+b.r);b.y+=ny*(newDistance+b.r);b.vx-=1.14*vn*nx;b.vy-=1.14*vn*ny;b.vx+=a.slope*450*step;if(b.last!==j&&b.cool<=0){play((j*2)%8,b.x,b.y,sceneSound('mallet'),.6,.3);b.last=j;b.cool=.12;}}}if(b.x<20||b.x>1180){b.x=clamp(b.x,20,1180);b.vx*=-.7;}}if(b.y>585){const target=s.targets.reduce((a,c)=>Math.abs(c.x-b.x)<Math.abs(a.x-b.x)?c:a);target.lit=.6;drum(target.i,target.x,target.y);b.age=100;}});s.balls=s.balls.filter(b=>b.age<22);s.targets.forEach(a=>a.lit=Math.max(0,(a.lit||0)-dt));},draw(){s.platforms.forEach((a,i)=>{const color=COLORS[i%8];line(a.x,a.y,a.x+a.w,a.y+a.w*a.slope,color,13);circle(a.x,a.y,8,color);circle(a.x+a.w,a.y+a.w*a.slope,8,color);if(settings.interaction==='create'&&i===s.selected){ring(a.x,a.y,17,'#f5f7d1',2);ring(a.x+a.w,a.y+a.w*a.slope,17,'#f5f7d1',2);}});s.targets.forEach(a=>{round(a.x-88,590,176,65,18,COLORS[a.i]+(a.lit?'ff':'a0'));text(['Deep drum','Hand drum','Snare','Wood','Shaker'][a.i],a.x,624,17,'#163e37');});s.balls.forEach(b=>{glow(b.x,b.y,35,COLORS[b.i]);circle(b.x,b.y,b.r,COLORS[b.i]);circle(b.x-4,b.y-5,4,'#ffffffa0');});if(!s.balls.length)text('Release a marble and follow its musical path',600,120,19,'#cbdbcb');}};
};

modules.pond=()=>{
 const s={ripples:[],id:0,met:new Set(),meetings:[]};
 function splash(p,soft=false){const n=clamp(Math.floor(p.x/150),0,7);play(n,p.x,p.y,sceneSound('pluck'),1.8,soft?.2:.5);s.ripples.push({x:p.x,y:p.y,r:8,age:0,n,id:s.id++,side:p.side||0});if(s.ripples.length>20)s.ripples.shift();p.next=elapsed+1.2;}
 return{state:s,down(p){splash(p);},move(p){if(elapsed>p.next){splash(p,true);}},update(dt){for(const p of pointers.values())if(elapsed>p.next)splash(p,true);s.ripples.forEach(r=>{r.r+=dt*(settings.energy==='calm'?42:65);r.age+=dt;});for(let i=0;i<s.ripples.length;i++)for(let j=i+1;j<s.ripples.length;j++){const a=s.ripples[i],b=s.ripples[j],key=a.id+':'+b.id,d=dist(a,b);if(d<a.r+b.r&&d>Math.abs(a.r-b.r)&&!s.met.has(key)){s.met.add(key);const x=(a.x+b.x)/2,y=(a.y+b.y)/2;audio.note(a.n,1.7,'bell',.12,-.3);audio.note(b.n+2,1.7,'bell',.12,.3);s.meetings.push({x,y,age:0});pulse(x,y,'#b8f4dc',35);}}s.ripples=s.ripples.filter(r=>r.age<6);s.meetings.forEach(a=>a.age+=dt);s.meetings=s.meetings.filter(a=>a.age<2);if(s.met.size>300)s.met.clear();},draw(){const gr=g.createRadialGradient(600,310,40,600,360,700);gr.addColorStop(0,'#438e9325');gr.addColorStop(1,'#042b4000');g.fillStyle=gr;g.fillRect(0,0,W,H);for(let i=0;i<12;i++){g.beginPath();for(let x=0;x<=W;x+=16){const y=110+i*45+Math.sin(x/200+elapsed*.13+i*.5)*14;x?g.lineTo(x,y):g.moveTo(x,y);}g.strokeStyle='#94d8d018';g.lineWidth=1;g.stroke();}s.ripples.forEach(r=>{g.globalAlpha=Math.max(0,1-r.age/6);const c=settings.players===2?PLAYER_COLORS[r.side]:COLORS[r.n];ring(r.x,r.y,r.r,c,2);ring(r.x,r.y,r.r*.8,c+'60',1);ring(r.x,r.y,r.r*.6,c+'30',1);g.globalAlpha=1;});s.meetings.forEach(a=>{g.globalAlpha=1-a.age/2;glow(a.x,a.y,100,'#d8ffe6');text('✧',a.x,a.y,30+a.age*15,'#ddffe7');g.globalAlpha=1;});}};
};

modules.aurora=()=>{
 const s={trails:[],chord:null};
 function move(p){const n=clamp(Math.floor((640-p.y)/58),0,9);p.voice?.set(n,p.x/W);if(n!==p.lastNote){pulse(p.x,p.y,PLAYER_COLORS[p.side||0],30);p.lastNote=n;}s.trails.push({x:p.x,y:p.y,age:0,side:p.side||0});if(s.trails.length>180)s.trails.shift();}
 return{state:s,down(p){p.voice=audio.note(clamp(Math.floor((640-p.y)/58),0,9),1,sceneSound('warm'),.48,p.side===0?-.45:.45,true);move(p);},move,up(p){p.voice?.stop();s.chord?.stop();s.chord=null;},update(dt){s.trails.forEach(a=>a.age+=dt);s.trails=s.trails.filter(a=>a.age<1.7);const both=new Set([...pointers.values()].map(p=>p.side));if(settings.players===2&&both.size>1&&!s.chord)s.chord=audio.note({midi:48},1,'warm',.18,0,true);if((both.size<2||!pointers.size)&&s.chord){s.chord.stop();s.chord=null;}},draw(){const touches=[...pointers.values()];for(let k=0;k<9;k++){const color=COLORS[(k+2)%8],shape=[];for(let x=0;x<=W;x+=20){let y=245+k*22+Math.sin(x/210+elapsed*.13+k*.35)*100+Math.sin(x/410-k*.3)*65;for(const p of touches)y+=(p.y-y)*Math.exp(-Math.pow((x-p.x)/180,2))*.32;shape.push({x,y});}const gr=g.createLinearGradient(0,150,0,570);gr.addColorStop(0,color+'00');gr.addColorStop(.5,color+'44');gr.addColorStop(1,color+'00');g.beginPath();shape.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));for(let i=shape.length-1;i>=0;i--)g.lineTo(shape[i].x,shape[i].y+75);g.closePath();g.fillStyle=gr;g.fill();g.beginPath();shape.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.lineWidth=2;g.strokeStyle=color+'60';g.stroke();}s.trails.forEach(a=>{circle(a.x,a.y,6+a.age*9,PLAYER_COLORS[a.side],(1-a.age/1.7)*.5);});touches.forEach(p=>{glow(p.x,p.y,130,PLAYER_COLORS[p.side]);ring(p.x,p.y,24,PLAYER_COLORS[p.side],2);circle(p.x,p.y,7,'#f1ffe1');});if(s.chord){glow(600,360,220,'#e9e6bc');text('A harmony together',600,585,20,'#e7f6d8');}else if(settings.players===2)text('Two touches bring the sky into harmony',600,590,18,'#b3d9d1');}};
};

modules.duet=()=>{
 const s={turns:false,side:0,pair:'harmony',pads:Array.from({length:8},(_,i)=>({x:i<4?80+(i%2)*230:675+(i%2)*230,y:200+Math.floor(i%4/2)*210,w:205,h:185,i,lit:0}))};
 const enter=(p,a)=>{if(!a||p.cell===a.i)return;const side=a.i<4?0:1;if(s.turns&&side!==s.side)return;p.cell=a.i;a.lit=1;const n=a.i%4,x=a.x+103,y=a.y+92;if(s.pair==='rhythm'){if(side===0)drum(n,x,y);else play(n+3,x,y,sceneSound('piano'),.9,.6);}else if(side===0)play(n+3,x,y,sceneSound('pluck'),.9,.55);else[0,2,4].forEach(k=>play(n+k,x,y,sceneSound('warm'),1.6,.28));};
 return{state:s,actions:[action('Melody & chords / beat & melody',()=>{s.pair=s.pair==='harmony'?'rhythm':'harmony';toast(s.pair==='harmony'?'Left: melody · Right: chords':'Left: beat · Right: melody');}),action('Together / take turns',()=>{s.turns=!s.turns;s.side=0;toast(s.turns?'Take turns: left side begins':'Play together');})],down(p){enter(p,s.pads.find(a=>hitRect(p,a)));},move(p){enter(p,s.pads.find(a=>hitRect(p,a)));},up(p){if(s.turns&&p.cell!==undefined)s.side=1-s.side;},update(dt){s.pads.forEach(a=>a.lit=Math.max(0,a.lit-dt));},draw(){round(35,140,535,500,28,'#76d6c00a');round(630,140,535,500,28,'#f9ce8c0a');line(600,160,600,615,'#badaca30',2);text(s.pair==='harmony'?'MELODY':'BEAT',305,151,23,PLAYER_COLORS[0]);text(s.pair==='harmony'?'CHORDS':'MELODY',895,151,23,PLAYER_COLORS[1]);s.pads.forEach(a=>{const side=a.i<4?0:1;g.globalAlpha=s.turns&&side!==s.side?.35:1;round(a.x,a.y,a.w,a.h,24,PLAYER_COLORS[side]);if(a.lit)ring(a.x+a.w/2,a.y+a.h/2,45+a.lit*15,'#ffffff80',3);const n=a.i%4;const title=s.pair==='rhythm'&&side===0?['Deep drum','Hand drum','Snare','Wood block'][n]:s.pair==='harmony'&&side===1?noteName(n)+' harmony':noteName(n+3);text(title,a.x+a.w/2,a.y+a.h/2,side===1&&s.pair==='harmony'?24:28,'#194038');g.globalAlpha=1;});if(s.turns)text((s.side===0?'Left':'Right')+' side’s turn',600,110,20,'#e5ecd0');}};
};

modules.paint=()=>{
 const s={paths:[],origin:null,playing:false,time:0,events:[],cursor:0,length:0};
 function add(p){const path=p.path;if(!path||path.length>=240)return;const last=path.at(-1);if(last&&dist(p,last)<8)return;const n=clamp(Math.floor((630-p.y)/58),0,9);const point={x:p.x,y:p.y,n,t:elapsed-s.origin,sounded:false};path.push(point);if(n!==p.lastNote||elapsed-(p.lastSound||0)>.25){play(n,p.x,p.y,sceneSound('piano'),.5,.45);point.sounded=true;p.lastNote=n;p.lastSound=elapsed;}}
 return{state:s,actions:[action('Play drawing / stop',()=>{if(s.playing){s.playing=false;return;}s.events=s.paths.flat().filter(p=>p.sounded).sort((a,b)=>a.t-b.t);if(!s.events.length){toast('Draw a melody first.');return;}const base=s.events[0].t;s.events=s.events.map(e=>({...e,t:e.t-base}));s.length=s.events.at(-1).t+.8;s.playing=true;s.time=0;s.cursor=0;toast('Playing with your original timing.');}),action('Clear drawing',()=>{s.paths=[];s.origin=null;s.playing=false;})],down(p){s.playing=false;if(s.origin===null)s.origin=elapsed;if(s.paths.length>=12)s.paths.shift();p.path=[];p.path.color=settings.players===2?PLAYER_COLORS[p.side]:COLORS[s.paths.length%8];s.paths.push(p.path);add(p);},move:add,update(dt){if(!s.playing)return;s.time+=dt;while(s.cursor<s.events.length&&s.events[s.cursor].t<=s.time){const e=s.events[s.cursor++];play(e.n,e.x,e.y,sceneSound('piano'),.5,.45);s.head=e;}if(s.time>s.length)s.playing=false;},draw(){for(let i=0;i<6;i++)line(60,155+i*80,1140,155+i*80,'#d7dfee0c',1);s.paths.forEach(path=>{if(!path.length)return;g.strokeStyle=path.color;g.lineWidth=7;g.lineCap='round';g.lineJoin='round';g.beginPath();path.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.stroke();path.filter(p=>p.sounded).forEach(p=>circle(p.x,p.y,7,path.color));});if(s.playing&&s.head){glow(s.head.x,s.head.y,80,'#f1e2ad');circle(s.head.x,s.head.y,11,'#fff3c8');}if(!s.paths.length){text('Your hand is the melody',600,320,34,'#dde4f1');text('Your pauses and movement become part of the music.',600,368,19,'#aebacf');}if(s.playing)text('Your timing · '+s.time.toFixed(1)+' seconds',600,605,17,'#d5dfd8');}};
};

modules.echo=()=>{
 const s={pads:padPositions(4,1),record:[],reply:[],origin:null,mode:'copy',speaking:false,clock:0,cursor:0,last:0};s.pads.forEach(p=>{p.y=405;p.h=150;});
 function answer(){if(!s.record.length){toast('Play a pattern first.');return;}const base=s.record[0].t;s.reply=s.record.map((e,i)=>({...e,n:s.mode==='copy'?e.n:(e.n+(i%2?1:2))%4,t:e.t-base}));s.speaking=true;s.clock=0;s.cursor=0;}
 return{state:s,actions:[action('Hear an answer',answer),action('Copy / improvise',()=>{s.mode=s.mode==='copy'?'answer':'copy';toast(s.mode==='copy'?'Copying your notes, rhythm, and pauses':'A new melody with your rhythm');}),action('New pattern',()=>{s.record=[];s.origin=null;s.speaking=false;})],down(p){const a=s.pads.find(a=>hitRect(p,a));if(!a)return;s.speaking=false;if(s.origin===null)s.origin=elapsed;if(s.record.length>=12)s.record.shift();const e={n:a.i,t:elapsed-s.origin,duration:.5};s.record.push(e);p.event=e;p.began=elapsed;play(a.i,a.x+a.w/2,a.y+a.h/2,sceneSound('mallet'),.6,.6);},up(p){if(p.event)p.event.duration=clamp(elapsed-p.began+.15,.2,2);},update(dt){if(!s.speaking)return;s.clock+=dt;while(s.cursor<s.reply.length&&s.reply[s.cursor].t<=s.clock){const e=s.reply[s.cursor++],a=s.pads[e.n];play(e.n,a.x+a.w/2,a.y+a.h/2,sceneSound('mallet'),e.duration,.6);s.last=elapsed;}const end=s.reply.at(-1);if(end&&s.cursor===s.reply.length&&s.clock>end.t+end.duration)s.speaking=false;},draw(){character('bird',600,230,230,s.speaking?Math.max(0,1-(elapsed-s.last)*2):.15);text(s.speaking?'My turn!':s.record.length?'Ready to hear your pattern?':'Your turn. I’m listening.',600,361,24,'#e0edd9');s.pads.forEach(a=>{round(a.x,a.y,a.w,a.h,24,COLORS[a.i]);label(a.i,a.x+a.w/2,a.y+a.h/2,34);});if(s.record.length){const first=s.record[0].t,total=Math.max(1,s.record.at(-1).t-first);line(320,607,880,607,'#c5d7b433',2);s.record.forEach(e=>circle(320+(e.t-first)/total*560,607,8,COLORS[e.n]));text('Your notes and pauses',600,645,15,'#a6bfa9');}}};
};

modules.ocean=()=>{
 const data=[['whale','Deep whale',3],['fish','Fish melody',5],['jellyfish','Jelly bells',6],['octopus','Octopus beat',0],['shell','Shell harmony',4],['crab','Crab clicks',7]];const s={on:new Set(),step:-1,clock:0,items:data.map((a,i)=>({animal:a[0],name:a[1],part:a[2],x:220+(i%3)*380,y:240+Math.floor(i/3)*250,i,lit:0}))};
 return{state:s,actions:[action('Quiet ocean',()=>s.on.clear())],down(p){const a=nearest(p,s.items,140);if(a){s.on.has(a.i)?s.on.delete(a.i):s.on.add(a.i);pulse(a.x,a.y,COLORS[a.i]);}},update(dt){s.items.forEach(a=>a.lit=Math.max(0,a.lit-dt*2));loopTick(s,dt,16,i=>s.items.forEach(a=>{if(s.on.has(a.i)){playLayer(a.part,i,a.x,a.y,true);if(i%2===0)a.lit=1;}}));},draw(){for(let i=0;i<7;i++){g.beginPath();for(let x=0;x<=W;x+=20){const y=110+i*80+Math.sin(x/200+elapsed*.2)*10;x?g.lineTo(x,y):g.moveTo(x,y);}g.strokeStyle='#7bc9d714';g.lineWidth=2;g.stroke();}s.items.forEach(a=>{const on=s.on.has(a.i);if(on)glow(a.x,a.y,120,COLORS[a.i]);ring(a.x,a.y,94,on?COLORS[a.i]+'80':'#d7eeef13',2);character(a.animal,a.x,a.y,190,on?a.lit:.05);text(a.name,a.x,a.y+115,20,on?'#edf6df':'#a2c6cf');});}};
};

modules.stones=()=>{
 const tunes=[[0,0,7,7,9,9,7,5,5,4,4,2,2,0],[0,2,4,0,0,2,4,0,4,5,7,4,5,7],[0,2,4,5,7,9,11,12,11,9,7,5,4,2,0]],names=['Twinkle, Twinkle','Frère Jacques','Up and down'];const s={pos:0,count:0,tune:0,hop:1,from:0,items:Array.from({length:7},(_,i)=>({x:140+i*152,y:415+Math.sin(i*.95)*60,i}))};
 function advance(){const a=s.items[s.pos],n=tunes[s.tune][s.count%tunes[s.tune].length];audio.note({midi:60+n},.9,sceneSound('piano'),.6,(a.x/W-.5));pulse(a.x,a.y,COLORS[s.count%8]);s.from=s.pos;s.count++;s.pos=s.count%7;s.hop=0;}
 return{state:s,actions:[action('Next melody',()=>{s.tune=(s.tune+1)%3;s.count=0;s.pos=0;s.from=0;s.hop=1;toast(names[s.tune]);})],down(p){const a=nearest(p,s.items,90);if(a&&a.i===s.pos)advance();else if(a){pulse(a.x,a.y,'#a7c0b1',20);toast('Follow the glowing stone.');}},key:advance,update(dt){s.hop=Math.min(1,s.hop+dt*3);},draw(){s.items.forEach(a=>{g.save();g.translate(a.x,a.y);g.scale(1,.52);circle(0,0,64,a.i===s.pos?'#ddefa2':'#739f864d');ring(0,0,64,'#aed0ae40',2);g.restore();text(String(a.i+1),a.x,a.y,21,a.i===s.pos?'#345043':'#b0c8b0');});const from=s.items[s.from],to=s.items[s.pos],t=settings.energy==='calm'?1:s.hop;character('frog',from.x+(to.x-from.x)*t,from.y+(to.y-from.y)*t-78-Math.sin(t*Math.PI)*45,140,0);text(names[s.tune],600,168,25,'#dfebd4');text('Touch the glowing stone',600,580,20,'#b5ceb8');}};
};

// Route touch-anywhere input to a reachable sound target in every experience.
function accessiblePoint(p){if(settings.interaction!=='touch')return p;const state=scene.state||{};let target=null;if(current.id==='stones')target=state.items[state.pos];else if(state.pads?.length){const a=state.pads.reduce((best,a)=>{const center={x:a.x+a.w/2,y:a.y+a.h/2};return !best||dist(p,center)<dist(p,best)?center:best;},null);target=a;}else if(state.items?.length&&!['fireflies'].includes(current.id)){target=nearest(p,state.items,2000);}else if(current.id==='train'){target={x:158+clamp(Math.floor((p.x-100)/127),0,7)*127,y:350};}if(target)return{...p,x:target.x,y:target.y};return p;}
// Preserve the finger's player identity even when it crosses the screen.
const previousDown=pointerDown;
canvas.removeEventListener('pointerdown',previousDown);
canvas.addEventListener('pointerdown',e=>{if(e.button>0)return;e.preventDefault();ensureStart();if(transport.playing){transport.stop();audio.stop();}if(settings.players===1&&pointers.size>0)return;const position=locationOf(e);if(settings.guard&&lastTap&&performance.now()-lastTap.at<200&&dist(position,lastTap)<65)return;lastTap={...position,at:performance.now()};if(pointers.size>=10)return;let p={...position,id:e.pointerId,side:settings.players===2?(position.x<W/2?0:1):0};p=accessiblePoint(p);pointers.set(e.pointerId,p);canvas.setPointerCapture?.(e.pointerId);scene.down?.(p);if(settings.interaction==='touch'&&current.id==='fireflies'&&p.object)play(p.object.n,p.object.x,p.object.y,'bell',1.2,.4);});
const previousMove=pointerMove;
canvas.removeEventListener('pointermove',previousMove);
canvas.addEventListener('pointermove',e=>{if(settings.interaction==='touch')return;previousMove(e);});

const oldApplySettings=applySettings;
applySettings=function(){oldApplySettings();for(const k of ['interaction','reverb','sustain'])$(k).value=String(settings[k]);$('classroom').checked=settings.classroom;$('reverbOut').textContent=settings.reverb+'%';$('sustainOut').textContent=settings.sustain.toFixed(1)+'×';document.body.classList.toggle('focus',settings.classroom);document.body.classList.toggle('createMode',settings.interaction==='create');$('studentPlayers').textContent=settings.players===2?'● ● Together':'● One player';renderActions();};
for(const k of ['interaction','reverb','sustain','classroom'])$(k).addEventListener('input',()=>{settings[k]=k==='classroom'?$(k).checked:k==='interaction'?$(k).value:Number($(k).value);applySettings();saveLocal('sg-settings',settings);if(k==='interaction')toast({touch:'Every touch can find a sound.',explore:'Explore positions, movement, and sound.',create:'Arrange, record, and hear your music.'}[settings.interaction]);});
renderActions=function(){const t=$('activityActions');t.replaceChildren();for(const a of scene?.actions||[]){if(a.createOnly&&settings.interaction!=='create')continue;const b=document.createElement('button');b.textContent=a.label;b.onclick=()=>{ensureStart();a.fn();};t.append(b);}};
const oldSelect=selectExperience;
selectExperience=function(id){if(transport.recording)transport.finish();transport.stop();oldSelect(id);if(id==='duet')setPlayers(2);$('studentTitle').textContent=current.name;$('studentInstruction').textContent=current.instruction;$('studentPlayers').textContent=settings.players===2?'● ● Together':'● One player';};
const oldSetPlayers=setPlayers;
setPlayers=function(n){oldSetPlayers(n);$('studentPlayers').textContent=n===2?'● ● Together':'● One player';};
$('studentBrowse').onclick=()=>$('browse').click();$('studentSettings').onclick=()=>$('settingsBtn').click();$('studentFull').onclick=()=>$('fullscreen').click();$('studentPlayers').onclick=()=>setPlayers(settings.players===1?2:1);
$('recordBtn').onclick=()=>{ensureStart();transport.recording?transport.finish():transport.begin();};
$('replayBtn').onclick=()=>{if(transport.playing){transport.stop();audio.stop();}else transport.replay();};
const oldQuiet=$('quiet').onclick;$('quiet').onclick=()=>{oldQuiet();$('studentQuiet').textContent=muted?'▷ Resume':'◼ Quiet';$('studentQuiet').setAttribute('aria-pressed',String(muted));};$('studentQuiet').onclick=()=>$('quiet').click();
$('studentReset').onclick=()=>{if(transport.recording)transport.finish();transport.stop();$('reset').click();};
$('focus').onclick=()=>{settings.classroom=true;applySettings();saveLocal('sg-settings',settings);};$('exitFocus').onclick=()=>{settings.classroom=false;applySettings();saveLocal('sg-settings',settings);};
// Show performance controls in teacher view too, without a second set of state.
$('focus').textContent='▣ Classroom screen';

const previews=new Map();const oldRenderLibrary=renderLibrary;
renderLibrary=function(){oldRenderLibrary();for(const b of $('experienceGrid').querySelectorAll('.experience')){const title=b.querySelector('strong')?.textContent;const e=EXPERIENCES.find(e=>e.name===title);if(e&&previews.has(e.id)){const mini=b.querySelector('.mini');mini.replaceChildren();const img=document.createElement('img');img.src=previews.get(e.id);img.alt='';mini.append(img);}}};
function buildPreviews(){if(pointers.size||transport.recording||transport.playing)return;const saved={current,scene,muted,elapsed,energy:settings.energy};const width=canvas.width,height=canvas.height;try{muted=true;settings.energy='colorful';canvas.width=480;canvas.height=288;EXPERIENCES.forEach(e=>{current=e;scene=modules[e.id]();const s=scene.state||{};if(e.id==='gravity'){s.balls=[{x:230,y:230,r:22,i:1,side:0},{x:955,y:210,r:22,i:3,side:1}];}if(e.id==='marbles')s.balls=[{x:470,y:218,r:15,i:1}];if(e.id==='pond')s.ripples=[{x:450,y:310,r:120,age:1,n:3,side:0},{x:685,y:380,r:150,age:1,n:1,side:1}];if(e.id==='paint'){const path=Array.from({length:30},(_,i)=>({x:140+i*32,y:360+Math.sin(i*.25)*110,n:i%8,t:i,sounded:i%5===0}));path.color=COLORS[3];s.paths=[path];}if(s.on)s.on=new Set([0,3,5]);if(e.id==='fireflies')s.items=Array.from({length:9},(_,i)=>({x:170+i*100,y:280+Math.sin(i)*115,n:i%8,lit:.3}));if(e.id==='blossoms')s.notes=[0,-1,1,-1,0,2,1,-1,0,-1,1,2,0,-1,1,-1];if(e.id==='kaleido')s.points=Array.from({length:15},(_,i)=>({x:110+i*10,y:20+i*9,c:COLORS[i%8],age:.8}));g.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);drawBackground();scene.draw();previews.set(e.id,canvas.toDataURL('image/jpeg',.75));});}finally{current=saved.current;scene=saved.scene;muted=saved.muted;elapsed=saved.elapsed;settings.energy=saved.energy;canvas.width=width;canvas.height=height;render(0);}renderLibrary();}
sprite.onload=()=>buildPreviews();
// Preserve previous preferences and choose the scene's palette for fresh setups.
applySettings();selectExperience('squares');resize();syncTransport();buildPreviews();requestAnimationFrame(tick);
